-- Run only inside a newly created disposable B21 database.
BEGIN;
DO $$ BEGIN
  IF current_database() NOT IN ('b21_fresh_review','b21_baseline_review') OR NOT EXISTS (SELECT 1 FROM b21_guard.b21_owned_test_marker WHERE marker='mgl850-b21-review-f605e66-20261119') THEN RAISE EXCEPTION 'Refusing non-B21 disposable database'; END IF;
END $$;
CREATE FUNCTION pg_temp.expect_reject(statement text, label text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE actual_constraint text;
BEGIN
  BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE <> (CASE label WHEN 'duplicate interval' THEN '23505' WHEN 'duplicate market id' THEN '23505' WHEN 'snapshot interval mismatch' THEN 'P0001' WHEN 'pending snapshot allocation' THEN 'P0001' WHEN 'other market snapshot' THEN 'P0001' WHEN 'different finalized snapshot' THEN 'P0001' WHEN 'duplicate allocation' THEN '23505' WHEN 'duplicate allocation terms with different id' THEN '23505' WHEN 'same buyer seller' THEN '23514' WHEN 'zero quantity' THEN '23514' WHEN 'negative quantity' THEN '23514' WHEN 'immutable quantity' THEN 'P0001' WHEN 'allocation deletion before intent' THEN 'P0001' WHEN 'finalized snapshot mutation' THEN 'P0001' WHEN 'finalized participant measurement mutation' THEN 'P0001' WHEN 'finalized participant measurement deletion' THEN 'P0001' WHEN 'bigint overflow' THEN '22003' WHEN 'wrong settlement amount' THEN 'P0001' WHEN 'wrong settlement market' THEN 'P0001' WHEN 'duplicate intent' THEN '23505' WHEN 'immutable payment amount' THEN 'P0001' WHEN 'intent deletion before evidence' THEN 'P0001' WHEN 'confirmed without evidence at constraint check' THEN 'P0001' WHEN 'projected without evidence at constraint check' THEN 'P0001' WHEN 'evidence amount mismatch' THEN 'P0001' WHEN 'evidence chain mismatch' THEN 'P0001' WHEN 'evidence token mismatch' THEN 'P0001' WHEN 'evidence buyer mismatch' THEN 'P0001' WHEN 'evidence seller mismatch' THEN 'P0001' WHEN 'evidence contract mismatch' THEN 'P0001' WHEN 'duplicate verified event' THEN '23505' WHEN 'verified evidence mutation' THEN 'P0001' WHEN 'referenced user delete' THEN '23503' ELSE 'NO_MATCH' END) THEN RAISE; END IF; GET STACKED DIAGNOSTICS actual_constraint = CONSTRAINT_NAME; IF SQLSTATE = '23505' AND label = 'duplicate market id' AND actual_constraint <> 'V2Market_pkey' THEN RAISE; END IF; IF SQLSTATE = '23505' AND label = 'duplicate allocation' AND actual_constraint <> 'V2Allocation_pkey' THEN RAISE; END IF; IF SQLSTATE = '23505' AND label = 'duplicate intent' AND actual_constraint <> 'V2SettlementIntent_allocationId_key' THEN RAISE; END IF; IF SQLSTATE = '23514' AND label IN ('same buyer seller','zero quantity','negative quantity') AND actual_constraint <> 'V2Allocation_terms_check' THEN RAISE; END IF; IF SQLSTATE = '23505' AND label = 'duplicate interval' AND actual_constraint <> 'V2Market_namespace_intervalStart_intervalEnd_key' THEN RAISE; END IF; IF SQLSTATE = '23505' AND label = 'duplicate allocation terms with different id' AND actual_constraint <> 'V2Allocation_logical_key' THEN RAISE; END IF; IF SQLSTATE = 'P0001' AND SQLERRM <> (CASE label WHEN 'snapshot interval mismatch' THEN 'snapshot market interval mismatch' WHEN 'pending snapshot allocation' THEN 'allocation requires finalized snapshot' WHEN 'other market snapshot' THEN 'allocation requires finalized snapshot' WHEN 'different finalized snapshot' THEN 'market already locked to another snapshot' WHEN 'immutable quantity' THEN 'allocation facts are immutable' WHEN 'allocation deletion before intent' THEN 'allocation facts are immutable' WHEN 'finalized snapshot mutation' THEN 'finalized snapshot is immutable; use supersession' WHEN 'finalized participant measurement mutation' THEN 'finalized participant measurement is immutable' WHEN 'finalized participant measurement deletion' THEN 'finalized participant measurement is immutable' WHEN 'wrong settlement amount' THEN 'intent allocation mismatch' WHEN 'wrong settlement market' THEN 'intent allocation mismatch' WHEN 'immutable payment amount' THEN 'intent facts are immutable' WHEN 'intent deletion before evidence' THEN 'intent facts are immutable' WHEN 'confirmed without evidence at constraint check' THEN 'confirmed intent requires verified evidence' WHEN 'projected without evidence at constraint check' THEN 'confirmed intent requires verified evidence' WHEN 'evidence amount mismatch' THEN 'evidence terms mismatch' WHEN 'evidence chain mismatch' THEN 'evidence terms mismatch' WHEN 'evidence token mismatch' THEN 'evidence terms mismatch' WHEN 'evidence buyer mismatch' THEN 'evidence terms mismatch' WHEN 'evidence seller mismatch' THEN 'evidence terms mismatch' WHEN 'evidence contract mismatch' THEN 'evidence terms mismatch' WHEN 'verified evidence mutation' THEN 'verified evidence is immutable' ELSE 'NO_MATCH' END) THEN RAISE; END IF; RAISE NOTICE 'PASS reject: % (SQLSTATE %)', label, SQLSTATE; RETURN; END;
  RAISE EXCEPTION 'unexpectedly accepted: %', label;
END $$;
